REM | All rights reserved.                                                        |
REM +=============================================================================+
REM | DESCRIPTION
REM |   Check that sequences have max_value as defined in EBS 12.2.13.
REM |   This script is specific to EBS version 12.2.13.
REM |
REM | CHANGE LOG:
REM |     1/10/2024 gbuzsaki/jwsmith Bug 36119960 - Script creation.
REM +=======================================================================+

SET FEEDBACK OFF;
SET ECHO OFF;

WHENEVER OSERROR EXIT FAILURE ROLLBACK;
WHENEVER SQLERROR EXIT FAILURE ROLLBACK;

REM
REM  Spool results to adcheckseqmax.out file.
REM
spool adcheckseqmax.out

column sequence_owner format A15
column sequence_name format A30

prompt =========================================================================
prompt =           Checking EBS Sequence MAX_VALUE settings (12.2.13) 
prompt =========================================================================

select sequence_owner, sequence_name, 2147483647 dev_max, max_value, last_number from dba_sequences where sequence_owner='APPLSYS' and sequence_name='AD_ANALYSIS_RUN_BUG_ID_S' and max_value>=2147483648;                                      
